/* Signal Sprint arcade route */
.signal-game {
  color: var(--color-fg);
}

.signal-game .live-dot,
.signal-game .signal-status i {
  display: inline-block;
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 999px;
  background: var(--color-ok);
  box-shadow: 0 0 12px rgba(95, 227, 173, 0.8);
}

.signal-game .signal-score-card,
.signal-game .signal-console,
.signal-game .signal-side-card {
  background: linear-gradient(145deg, rgba(14, 30, 45, 0.96), rgba(7, 17, 28, 0.98));
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.18), inset 0 1px rgba(255, 255, 255, 0.025);
}

.signal-game .signal-score-card {
  min-width: 13rem;
  justify-content: space-between;
}

.signal-game .signal-hud,
.signal-game .signal-controls {
  background: rgba(8, 19, 30, 0.94);
}

.signal-game .signal-status {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--color-subtle);
  font: 600 0.58rem/1 var(--font-mono);
  letter-spacing: 0.14em;
}

.signal-game .signal-status i {
  width: 0.36rem;
  height: 0.36rem;
  background: var(--color-subtle);
  box-shadow: none;
}

.signal-game .signal-status.is-live {
  color: var(--color-ok);
}

.signal-game .signal-status.is-live i {
  background: var(--color-ok);
  box-shadow: 0 0 10px rgba(95, 227, 173, 0.8);
  animation: sprint-blink 1.5s ease-in-out infinite;
}

.signal-game .signal-heart {
  display: block;
  width: 0.72rem;
  height: 0.45rem;
  border: 1px solid rgba(255, 129, 151, 0.35);
  border-radius: 2px;
  background: rgba(255, 129, 151, 0.06);
  transform: skewX(-18deg);
}

.signal-game .signal-heart.is-live {
  border-color: var(--color-danger);
  background: var(--color-danger);
  box-shadow: 0 0 10px rgba(255, 129, 151, 0.35);
}

.signal-game .signal-icon-button,
.signal-game .signal-move-button,
.signal-game .signal-boost-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.45rem;
  border: 1px solid var(--color-border);
  border-radius: 0.6rem;
  background: rgba(17, 34, 51, 0.72);
  color: var(--color-fg);
  transition: border-color 160ms ease, color 160ms ease, background 160ms ease, transform 160ms ease;
}

.signal-game .signal-icon-button {
  width: 2.45rem;
  height: 2.45rem;
}

.signal-game .signal-move-button {
  width: 2.75rem;
  height: 2.75rem;
  touch-action: manipulation;
}

.signal-game .signal-boost-button {
  gap: 0.45rem;
  padding: 0 0.8rem;
  color: var(--color-accent);
  font: 600 0.62rem/1 var(--font-mono);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.signal-game .signal-boost-button span {
  display: inline-grid;
  min-width: 1.15rem;
  height: 1.15rem;
  place-items: center;
  border-radius: 999px;
  background: rgba(72, 217, 255, 0.12);
  color: var(--color-fg);
}

.signal-game .signal-icon-button:hover,
.signal-game .signal-move-button:hover:not(:disabled),
.signal-game .signal-boost-button:hover:not(:disabled) {
  border-color: rgba(72, 217, 255, 0.65);
  background: rgba(72, 217, 255, 0.12);
  color: var(--color-accent);
}

.signal-game .signal-move-button:active:not(:disabled),
.signal-game .signal-boost-button:active:not(:disabled) {
  transform: translateY(1px) scale(0.98);
}

.signal-game button:disabled {
  cursor: not-allowed;
  opacity: 0.42;
}

.signal-game .signal-arena {
  position: relative;
  min-height: 28rem;
  aspect-ratio: 1.72 / 1;
  overflow: hidden;
  isolation: isolate;
  background:
    radial-gradient(ellipse at 50% 76%, rgba(32, 113, 142, 0.16), transparent 40%),
    linear-gradient(180deg, #071522 0%, #091a28 56%, #07131f 100%);
  transition: box-shadow 180ms ease;
}

.signal-game .signal-arena.has-shield {
  box-shadow: inset 0 0 0 1px rgba(72, 217, 255, 0.55), inset 0 0 60px rgba(72, 217, 255, 0.14);
}

.signal-game .arena-grid {
  position: absolute;
  z-index: -2;
  inset: -35% -10% -15%;
  opacity: 0.44;
  background-image:
    linear-gradient(rgba(67, 133, 161, 0.16) 1px, transparent 1px),
    linear-gradient(90deg, rgba(67, 133, 161, 0.14) 1px, transparent 1px);
  background-size: 4.1rem 3.2rem;
  transform: perspective(20rem) rotateX(38deg) scale(1.16);
  transform-origin: center 70%;
  mask-image: linear-gradient(180deg, transparent 4%, #000 28%, #000 88%, transparent);
}

.signal-game .arena-horizon {
  position: absolute;
  z-index: -1;
  top: 24%;
  right: 0;
  left: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(72, 217, 255, 0.32), transparent);
  box-shadow: 0 0 30px rgba(72, 217, 255, 0.16);
}

.signal-game .arena-lane {
  position: absolute;
  top: 12%;
  bottom: 8%;
  width: 1px;
  background: linear-gradient(180deg, transparent, rgba(72, 217, 255, 0.16) 22%, rgba(72, 217, 255, 0.13) 82%, transparent);
  transform: translateX(-50%);
}

.signal-game .arena-lane span {
  position: absolute;
  right: -0.5rem;
  bottom: 8%;
  left: -0.5rem;
  height: 22%;
  border-right: 1px solid rgba(72, 217, 255, 0.28);
  border-left: 1px solid rgba(72, 217, 255, 0.28);
  background: linear-gradient(180deg, transparent, rgba(72, 217, 255, 0.05));
  opacity: 0;
  transition: opacity 150ms ease;
}

.signal-game .arena-lane.is-current span {
  opacity: 1;
}

.signal-game .arena-label {
  position: absolute;
  right: 1.15rem;
  left: 1.15rem;
  display: flex;
  justify-content: space-between;
  color: rgba(174, 207, 220, 0.47);
  font: 600 0.53rem/1 var(--font-mono);
  letter-spacing: 0.12em;
  pointer-events: none;
}

.signal-game .arena-label span {
  color: rgba(174, 207, 220, 0.3);
}

.signal-game .arena-label-top {
  top: 1.15rem;
}

.signal-game .arena-label-bottom {
  bottom: 1rem;
}

.signal-game .signal-packet-token,
.signal-game .signal-runner {
  position: absolute;
  left: 50%;
  display: grid;
  place-items: center;
  transform: translate(-50%, -50%);
}

.signal-game .signal-packet-token {
  z-index: 2;
  width: clamp(1.45rem, 3.4vw, 2rem);
  height: clamp(1.45rem, 3.4vw, 2rem);
  border: 1px solid currentColor;
  border-radius: 0.55rem;
  font: 700 1rem/1 var(--font-mono);
  animation: packet-glow 1.4s ease-in-out infinite alternate;
}

.signal-game .signal-packet-token.fault {
  border-color: rgba(255, 129, 151, 0.78);
  background: rgba(101, 28, 50, 0.78);
  color: #ff8298;
  box-shadow: 0 0 20px rgba(255, 78, 118, 0.28), inset 0 0 12px rgba(255, 78, 118, 0.16);
}

.signal-game .signal-packet-token.signal {
  border-color: rgba(72, 217, 255, 0.8);
  background: rgba(11, 72, 91, 0.8);
  color: #8cecff;
  box-shadow: 0 0 22px rgba(72, 217, 255, 0.42), inset 0 0 12px rgba(72, 217, 255, 0.2);
}

.signal-game .signal-runner {
  z-index: 3;
  top: 80%;
  width: 2rem;
  height: 2.5rem;
  transition: left 100ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.signal-game .runner-core {
  position: relative;
  z-index: 1;
  width: 0.92rem;
  height: 1.18rem;
  border: 2px solid #d5faff;
  border-radius: 0.35rem 0.35rem 0.52rem 0.52rem;
  background: linear-gradient(145deg, #86edff, #2bbad9 72%);
  box-shadow: 0 0 18px rgba(72, 217, 255, 0.9), 0 0 42px rgba(72, 217, 255, 0.4);
}

.signal-game .runner-trail {
  position: absolute;
  bottom: -0.42rem;
  width: 0.45rem;
  height: 0.95rem;
  border-radius: 50%;
  background: linear-gradient(180deg, rgba(94, 227, 255, 0.72), transparent);
  filter: blur(3px);
}

.signal-game .signal-runner.is-hit .runner-core {
  border-color: #fff;
  background: #ff8298;
  box-shadow: 0 0 22px rgba(255, 78, 118, 0.9);
}

.signal-game .signal-runner.is-shielded::before {
  position: absolute;
  inset: -0.48rem;
  border: 1px solid rgba(102, 232, 255, 0.78);
  border-radius: 0.9rem;
  background: rgba(72, 217, 255, 0.08);
  box-shadow: 0 0 22px rgba(72, 217, 255, 0.4);
  content: "";
  animation: shield-pulse 1.1s ease-in-out infinite alternate;
}

.signal-game .game-toast {
  position: absolute;
  z-index: 4;
  top: 3.2rem;
  left: 50%;
  padding: 0.5rem 0.75rem;
  border: 1px solid rgba(72, 217, 255, 0.25);
  border-radius: 999px;
  background: rgba(5, 15, 25, 0.78);
  color: #b6f5ff;
  font: 500 0.58rem/1 var(--font-mono);
  letter-spacing: 0.04em;
  white-space: nowrap;
  transform: translateX(-50%);
  animation: toast-rise 2s ease both;
  pointer-events: none;
}

.signal-game .game-overlay {
  position: absolute;
  z-index: 5;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 1.25rem;
  background: rgba(3, 10, 17, 0.62);
  backdrop-filter: blur(5px);
}

.signal-game .game-overlay-card {
  width: min(100%, 23rem);
  padding: 1.65rem 1.5rem;
  border: 1px solid rgba(72, 217, 255, 0.2);
  border-radius: 1rem;
  background: linear-gradient(145deg, rgba(10, 26, 40, 0.97), rgba(5, 15, 24, 0.98));
  text-align: center;
  box-shadow: 0 20px 70px rgba(0, 0, 0, 0.4), 0 0 40px rgba(32, 143, 180, 0.08);
}

.signal-game .overlay-icon {
  display: grid;
  width: 2.7rem;
  height: 2.7rem;
  margin: 0 auto 1rem;
  place-items: center;
  border: 1px solid rgba(72, 217, 255, 0.32);
  border-radius: 0.8rem;
  background: rgba(72, 217, 255, 0.09);
  color: var(--color-accent);
  font: 1.4rem/1 var(--font-mono);
}

.signal-game .signal-primary-button {
  display: inline-flex;
  min-height: 2.8rem;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  padding: 0 1.15rem;
  border: 1px solid rgba(72, 217, 255, 0.75);
  border-radius: 0.55rem;
  background: var(--color-accent);
  color: #04111b;
  font-size: 0.75rem;
  font-weight: 700;
  transition: box-shadow 160ms ease, transform 160ms ease;
}

.signal-game .signal-primary-button:hover {
  box-shadow: 0 0 25px rgba(72, 217, 255, 0.3);
  transform: translateY(-1px);
}

.signal-game .signal-side-card {
  border-color: rgba(29, 50, 70, 0.85);
}

.signal-game .legend-token {
  display: grid;
  width: 1.7rem;
  height: 1.7rem;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid currentColor;
  border-radius: 0.45rem;
  font: 700 0.9rem/1 var(--font-mono);
}

.signal-game .signal-token {
  background: rgba(72, 217, 255, 0.08);
  color: var(--color-accent);
}

.signal-game .fault-token {
  background: rgba(255, 129, 151, 0.08);
  color: var(--color-danger);
}

.signal-game .pulse-token {
  background: rgba(237, 248, 255, 0.05);
  color: var(--color-fg);
}

.signal-game .keycap-group {
  display: flex;
  gap: 0.25rem;
}

.signal-game .keycap-group kbd {
  display: grid;
  min-width: 1.55rem;
  height: 1.5rem;
  padding: 0 0.25rem;
  place-items: center;
  border: 1px solid rgba(125, 150, 171, 0.3);
  border-bottom-width: 2px;
  border-radius: 0.28rem;
  color: #c4d6e0;
  font: 500 0.58rem/1 var(--font-mono);
}

.signal-game .signal-quote {
  border: 1px solid rgba(72, 217, 255, 0.17);
  background: radial-gradient(ellipse at 100% 0, rgba(72, 217, 255, 0.1), transparent 55%), rgba(10, 24, 36, 0.75);
}

@keyframes sprint-blink {
  50% { opacity: 0.45; }
}

@keyframes packet-glow {
  to { filter: brightness(1.2); }
}

@keyframes shield-pulse {
  to { opacity: 0.56; transform: scale(1.12); }
}

@keyframes toast-rise {
  0% { opacity: 0; transform: translate(-50%, 0.35rem); }
  12%, 72% { opacity: 1; transform: translate(-50%, 0); }
  100% { opacity: 0; transform: translate(-50%, -0.4rem); }
}

@media (max-width: 1023px) {
  .signal-game .signal-side-rail {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .signal-game .signal-quote {
    grid-column: 1 / -1;
  }
}

@media (max-width: 639px) {
  .signal-game .signal-arena {
    min-height: 24rem;
    aspect-ratio: 0.92 / 1;
  }

  .signal-game .signal-hud {
    align-items: flex-start;
  }

  .signal-game .signal-side-rail {
    grid-template-columns: 1fr;
  }

  .signal-game .signal-quote {
    grid-column: auto;
  }

  .signal-game .signal-score-card {
    min-width: 10rem;
  }

  .signal-game .game-toast {
    max-width: calc(100% - 1rem);
    overflow: hidden;
    text-overflow: ellipsis;
  }
}

@media (prefers-reduced-motion: reduce) {
  .signal-game *,
  .signal-game *::before,
  .signal-game *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

