import { writeFile } from "node:fs/promises";
const pages = await (await fetch("http://127.0.0.1:9222/json/list")).json();
const page = pages.find((item) => item.type === "page" && item.url.endsWith("/game"));
if (!page) throw new Error("Game tab not found");
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.addEventListener("open", resolve, { once: true }); ws.addEventListener("error", reject, { once: true }); });
let id = 0;
const pending = new Map();
ws.addEventListener("message", (event) => {
  const message = JSON.parse(event.data);
  if (message.id && pending.has(message.id)) {
    const { resolve, reject } = pending.get(message.id);
    pending.delete(message.id);
    message.error ? reject(new Error(message.error.message)) : resolve(message.result);
  }
});
const send = (method, params = {}) => new Promise((resolve, reject) => {
  const callId = ++id;
  pending.set(callId, { resolve, reject });
  ws.send(JSON.stringify({ id: callId, method, params }));
});
await send("Page.enable");
await send("Emulation.setDeviceMetricsOverride", { width: 1280, height: 900, deviceScaleFactor: 1, mobile: false });
await new Promise((resolve) => setTimeout(resolve, 900));
const screenshot = await send("Page.captureScreenshot", { format: "jpeg", quality: 82, captureBeyondViewport: false });
await writeFile("/tmp/opencode/game-latest.jpg", Buffer.from(screenshot.data, "base64"));
const before = await send("Runtime.evaluate", { expression: `({title: document.title, heading: document.querySelector('h1')?.innerText, status: document.querySelector('.signal-status')?.innerText, button: [...document.querySelectorAll('button')].find(x => x.innerText.includes('Start sprint'))?.innerText, viewport: [innerWidth, innerHeight]})`, returnByValue: true });
await send("Runtime.evaluate", { expression: `document.querySelector('.signal-primary-button')?.click()` });
await new Promise((resolve) => setTimeout(resolve, 1250));
await send("Input.dispatchKeyEvent", { type: "keyDown", key: "ArrowRight", code: "ArrowRight", windowsVirtualKeyCode: 39 });
await send("Input.dispatchKeyEvent", { type: "keyUp", key: "ArrowRight", code: "ArrowRight", windowsVirtualKeyCode: 39 });
const after = await send("Runtime.evaluate", { expression: `({status: document.querySelector('.signal-status')?.innerText, score: document.querySelector('.signal-hud .text-accent')?.innerText, runnerLeft: document.querySelector('.signal-runner')?.style.left, arena: !!document.querySelector('.signal-arena')})`, returnByValue: true });
console.log(JSON.stringify({ before: before.result.value, after: after.result.value, screenshot: "/tmp/opencode/game-latest.jpg" }, null, 2));
ws.close();

